name: "Close duplicate PRs"

# Closes open PRs that link to the same issue as an older open PR, keeping the
# oldest. To exempt a PR (e.g. after reopening one), add the `not-duplicate` label.

on:
  schedule:
    - cron: "0 */6 * * *"
  workflow_dispatch:
    inputs:
      dry_run:
        description: "Only log what would be closed"
        type: boolean
        default: true

permissions:
  pull-requests: write

concurrency:
  group: close-duplicate-prs
  cancel-in-progress: false

jobs:
  close-duplicates:
    if: github.repository == 'run-llama/llama_index'
    runs-on: ubuntu-latest
    steps:
      - name: Close PRs duplicating an older PR's linked issue
        uses: actions/github-script@v8
        env:
          DRY_RUN: ${{ github.event_name == 'workflow_dispatch' && inputs.dry_run }}
        with:
          script: |
            const dryRun = process.env.DRY_RUN === "true";
            const { owner, repo } = context.repo;
            const exemptLabel = "not-duplicate";
            const exemptAssociations = new Set(["OWNER", "MEMBER", "COLLABORATOR"]);
            const linkPattern = new RegExp(
              `(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\\s*:?\\s*(?:https://github\\.com/${owner}/${repo}/issues/|#)(\\d+)`,
              "gi",
            );

            const prs = [];
            let cursor = null;
            do {
              const res = await github.graphql(
                `query($owner: String!, $repo: String!, $cursor: String) {
                  repository(owner: $owner, name: $repo) {
                    pullRequests(states: OPEN, first: 100, after: $cursor) {
                      pageInfo { hasNextPage endCursor }
                      nodes {
                        number createdAt authorAssociation body
                        labels(first: 20) { nodes { name } }
                        closingIssuesReferences(first: 10) { nodes { number } }
                      }
                    }
                  }
                }`,
                { owner, repo, cursor },
              );
              const page = res.repository.pullRequests;
              prs.push(...page.nodes);
              cursor = page.pageInfo.hasNextPage ? page.pageInfo.endCursor : null;
            } while (cursor);

            // issue number -> open PRs linking it, oldest first
            const byIssue = new Map();
            for (const pr of prs) {
              const issues = new Set(pr.closingIssuesReferences.nodes.map((i) => i.number));
              for (const m of (pr.body || "").matchAll(linkPattern)) {
                issues.add(Number(m[1]));
              }
              for (const issue of issues) {
                if (!byIssue.has(issue)) byIssue.set(issue, []);
                byIssue.get(issue).push(pr);
              }
            }

            // PR number -> { issue, keep }
            const toClose = new Map();
            for (const [issue, linked] of byIssue) {
              if (linked.length < 2) continue;
              linked.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
              const keep = linked[0];
              for (const pr of linked.slice(1)) {
                if (exemptAssociations.has(pr.authorAssociation)) continue;
                if (pr.labels.nodes.some((l) => l.name === exemptLabel)) continue;
                if (!toClose.has(pr.number)) {
                  toClose.set(pr.number, { issue, keep: keep.number });
                }
              }
            }

            console.log(`Scanned ${prs.length} open PRs; ${toClose.size} duplicates found.`);

            for (const [number, { issue, keep }] of toClose) {
              console.log(`${dryRun ? "[dry run] Would close" : "Closing"} #${number} (duplicate of #${keep} for issue #${issue})`);
              if (dryRun) continue;

              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: number,
                body: [
                  `Closing as a duplicate: #${keep} was opened earlier for the same issue (#${issue}).`,
                  "We keep the oldest open PR per issue to avoid splitting review effort.",
                  "",
                  `If this PR differs meaningfully, please comment and a maintainer can reopen it and add the \`${exemptLabel}\` label.`,
                ].join("\n"),
              });

              await github.rest.pulls.update({
                owner,
                repo,
                pull_number: number,
                state: "closed",
              });
            }

